/* Offline discussion prototype. No fetch, storage, postMessage, upload or banking API. */
(()=>{
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>(n/100).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
const pages=[['dashboard','Dashboard'],['requests','Payment Requests'],['creditor','Creditor'],['debtor','Debtor'],['bank','Bank & Cash'],['history','Transaction History'],['activity','Activity History']];
const seed=[
 {id:'00124',supplier:'KOH SOON HUAT',customer:'SAMPLE',eta:'28 Oct 2026',age:'Today',at:'17 Oct 2026 09:15',by:'PURCHASE DEMO',request:43000,invoice:48000,cn:5000,paid:0,stage:'NEW',purpose:'Full payment',term:'30 days',due:'16 Nov 2026',note:'',basis:'INV',docs:true},
 {id:'00125',supplier:'HONG LEA',customer:'SCOMM',eta:'28 Oct 2026',age:'Yesterday',at:'16 Oct 2026 15:20',by:'PURCHASE DEMO',request:120000,invoice:120000,cn:0,paid:0,stage:'REVIEW',purpose:'Deposit',term:'Prepayment',due:'Before shipment',note:'Urgent shipment',basis:'PI',chase:true},
 {id:'00126',supplier:'KOH SOON HUAT',customer:'SAMPLE',eta:'30 Oct 2026',age:'2 Days ago',at:'15 Oct 2026 11:40',by:'PURCHASE DEMO',request:86000,invoice:96000,cn:10000,paid:0,stage:'PROBLEM',purpose:'Full payment',term:'30 days',due:'14 Nov 2026',note:'Supplier reminder',accNote:'Please replace the unclear invoice',basis:'INV',docs:false},
 {id:'00127',supplier:'HONG LEA',customer:'SCOMM',eta:'27 Oct 2026',age:'3 Days ago',at:'14 Oct 2026 14:05',by:'PURCHASE DEMO',request:200000,invoice:200000,cn:0,paid:80000,stage:'PARTIAL',purpose:'Full payment',term:'7 days',due:'21 Oct 2026',note:'',basis:'INV',proof:true,docs:true},
 {id:'00128',supplier:'KOH SOON HUAT',customer:'SAMPLE',eta:'26 Oct 2026',age:'4 Days ago',at:'13 Oct 2026 10:00',by:'PURCHASE DEMO',request:65000,invoice:65000,cn:0,paid:65000,stage:'PAID',purpose:'Balance',term:'14 days',due:'27 Oct 2026',basis:'INV',proof:true,docs:true,note:'',accNote:'Payment recorded'},
 {id:'00129',supplier:'HONG LEA',customer:'SCOMM',eta:'25 Oct 2026',age:'5 Days ago',at:'12 Oct 2026 16:30',by:'PURCHASE DEMO',request:90000,invoice:90000,cn:0,paid:0,stage:'UNKNOWN',purpose:'Part payment',term:'7 days',due:'19 Oct 2026',note:'',basis:'INV',accNote:'Bank result needs confirmation'}
];
let requests=structuredClone(seed),events=[],view='dashboard',filter='ALL',query='',company='NCT',proofSelected=false,actionFilter='';
const rows=()=>company==='NCT'?requests:[],status=r=>({NEW:['Waiting for Acc. response','gray'],REVIEW:['🔒 Reviewing Docs','gray'],PROBLEM:['⚠ Problem','red'],PARTIAL:['Partially Paid','orange'],PAID:['Fully Paid','green'],PROCESSING:['Processing','orange'],UNKNOWN:['⚠ Result Unknown','red']}[r.stage]);
const pill=r=>{const [text,tone]=status(r);return '<span class="pill '+tone+'">'+text+'</span>'},po=r=>'NCT-PO-'+r.id;
function showNotice(text){$('#notice').textContent=text;$('#notice').style.display='block';setTimeout(()=>$('#notice').style.display='none',3500);}
function audit(r,action,note){events.unshift({po:po(r),supplier:r.supplier,at:'17 Oct 2026 · Demo time',by:'ACCOUNT DEMO',action,note});}
function title(en,context=''){return '<div class="page-title"><div><h1>'+en+'</h1><p>'+(company==='NCT'?'North Cape Trading Sdn. Bhd.':'Global HR')+'</p></div>'+(context?'<span class="context">'+context+'</span>':'')+'<button class="refresh" data-refresh>Refresh</button></div>';}
function table(headers,widths,body,foot=''){return '<section class="panel"><div class="table-scroll"><table><colgroup>'+widths.map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup><thead><tr>'+headers.map(([text,cls])=>'<th class="'+(cls||'')+'">'+text+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div><div class="foot"><span>'+foot+'</span><span>'+company+' · Sample data</span></div></section>';}
const empty=n=>'<tr><td colspan="'+n+'" class="empty">No matching records</td></tr>';
const matches=(r,key)=>key==='ALL'||key==='NEW'&&r.stage==='NEW'||key==='CHASE'&&r.chase||key==='ISSUE'&&['PROBLEM','UNKNOWN'].includes(r.stage)||key==='WORK'&&['REVIEW','PARTIAL','PROCESSING'].includes(r.stage);
function cards(){return '<div class="cards">'+[['NEW','New Requests','orange'],['CHASE','Purchase Chase','orange'],['ISSUE','Needs Resolution','red'],['WORK','In Progress','']].map(([key,en,tone])=>{const count=rows().filter(r=>matches(r,key)).length;return '<button class="task-card '+(count?tone:'')+'" data-queue="'+key+'"><span>'+en+'</span><b>'+count+'</b></button>';}).join('')+'</div>';}
function toolbar(placeholder,options=''){return '<div class="toolbar"><input id="search" aria-label="Search records" placeholder="'+placeholder+'" value="'+esc(query)+'">'+options+'<span class="count" id="count"></span></div>';}
function queueTable(list){return table([['Requested'],['P.O. No.'],['Supplier'],['Purchase For'],['Request MYR','numeric'],['Paid MYR','numeric'],['Status'],['Pay Slip','center'],['Note from Purchase'],['Open','center']],[10,11,15,10,9,9,15,5,12,4],list.map(r=>'<tr><td><b>'+r.age+'</b><small>'+r.at+'</small><small>by '+r.by+'</small></td><td><button class="po-link" data-open="'+r.id+'">'+po(r)+'</button></td><td>'+r.supplier+'</td><td><b>'+r.customer+'</b><small>ETA: '+r.eta+'</small></td><td class="numeric"><b>'+money(r.request)+'</b><small>'+r.basis+(r.cn?' · CN −'+money(r.cn):'')+'</small></td><td class="numeric">'+money(r.paid)+'<small>Balance '+money(Math.max(0,r.request-r.paid))+'</small></td><td>'+pill(r)+(r.chase?'<span class="chase" title="Purchase chased">ϟ</span>':'')+'</td><td class="center"><button class="slip" '+(r.proof?'data-proof="'+r.id+'"':'disabled')+' aria-label="'+(r.proof?'View':'Missing')+' pay slip '+po(r)+'">↓</button></td><td>'+esc(r.note||'—')+(r.note?'<small>'+r.by+'</small>':'')+'</td><td class="center"><button class="po-link" data-open="'+r.id+'">→</button></td></tr>').join('')||empty(10),'Amounts refer to this request. Reconcile the supporting INV and applicable CN; the PO amount is a reference.');}
function dashboard(){const work=rows().filter(r=>r.stage!=='PAID');return title('Dashboard')+cards()+toolbar('P.O. · Supplier · Customer')+queueTable(work)+'<div class="split"><section class="panel"><div class="panel-title"><h2>Reconciliation</h2></div><div style="padding:0 12px 12px"><p>Final INV missing <b>'+(company==='NCT'?1:0)+'</b></p><p>Receiving discrepancy <b>'+(company==='NCT'?1:0)+'</b></p><p>Supplier credits <b>'+(company==='NCT'?1:0)+'</b></p><button data-page="creditor">Open Creditor →</button></div></section><section class="panel"><div class="panel-title"><h2>Latest Activity</h2><button data-page="activity">View all →</button></div><div style="padding:0 12px 12px">'+activityPreview()+'</div></section></div><p class="legend">Orange indicates pending action, red an unresolved problem, and green a completed item. Only submitted requests enter Payment Requests. Legacy records remain in Creditor reconciliation.</p>';}
function payments(){return title('Payment Requests')+cards()+toolbar('P.O. · Supplier · Customer','<select id="requestFilter" aria-label="Request status"><option value="ALL">All Requests</option>'+[['NEW','Awaiting Review'],['CHASE','Purchase Chase'],['ISSUE','Problems'],['WORK','In Progress']].map(([k,t])=>'<option value="'+k+'" '+(filter===k?'selected':'')+'>'+t+'</option>').join('')+'</select>')+queueTable(rows().filter(r=>matches(r,filter)))+'<p class="legend">Open a request to review it. Taking ownership locks Purchase editing. Confirm there is no processing or unknown payment before returning it.</p>';}
function creditor(){const list=rows().filter(r=>r.basis==='INV'&&r.stage!=='PAID');return title('Creditor')+toolbar('Supplier · INV · P.O.')+table([['Supplier'],['Invoice'],['P.O. No.'],['INV MYR','numeric'],['CN MYR','numeric'],['Paid MYR','numeric'],['Balance MYR','numeric'],['Due'],['Reconciliation']],[15,12,12,9,8,9,10,10,15],list.map(r=>'<tr><td><b>'+r.supplier+'</b></td><td>INV-'+r.id+'</td><td><button class="po-link" data-open="'+r.id+'">'+po(r)+'</button></td><td class="numeric">'+money(r.invoice)+'</td><td class="numeric">'+money(r.cn)+'</td><td class="numeric">'+money(r.paid)+'</td><td class="numeric"><b>'+money(r.invoice-r.cn-r.paid)+'</b></td><td>'+r.due+'</td><td>'+pill(r)+'</td></tr>').join('')||empty(9),'Payables use final invoices, applicable credit notes, recorded payments and applied credit. Each PO is counted once.')+'<div class="split"><section class="panel"><div class="panel-title"><h2>Supplier Credit</h2></div><div style="padding:0 12px 12px">'+(company==='NCT'?'<b>HONG LEA · MYR 50.00</b><p>CN-DEMO-09 · Confirmed available credit</p><button data-credit>Review credit</button>':'No supplier credit')+'</div></section><section class="panel"><div class="panel-title"><h2>Legacy & Exceptions</h2></div><div style="padding:0 12px 12px">'+(company==='NCT'?'<p>One legacy PO has payment records but no complete current request.</p><button data-legacy>Reconcile legacy</button>':'No legacy issues')+'</div></section></div>';}
function debtor(){const list=company==='NCT'?[['SCOMM','SI-DEMO-001','MYR',540000,300000,'24 Oct 2026'],['SAMPLE','SI-DEMO-002','MYR',96000,0,'30 Oct 2026'],['SCOMM EXPORT','SI-DEMO-003','SGD',120000,0,'28 Oct 2026']]:[];return title('Debtor')+toolbar('Customer · Sales Invoice')+'<div class="money-cards">'+['MYR','SGD'].map(currency=>'<section class="money-card"><span>'+currency+' Outstanding</span><b>'+(company==='NCT'?money(list.filter(r=>r[2]===currency).reduce((n,r)=>n+r[3]-r[4],0)):'—')+'</b><small>Currencies are displayed separately and never combined.</small></section>').join('')+'</div>'+table([['Customer'],['Sales Invoice'],['Currency'],['Invoice Amount','numeric'],['Received','numeric'],['Balance','numeric'],['Due'],['Open']],[20,16,8,12,12,12,12,8],list.map(r=>'<tr><td><b>'+r[0]+'</b></td><td>'+r[1]+'</td><td>'+r[2]+'</td><td class="numeric">'+money(r[3])+'</td><td class="numeric">'+money(r[4])+'</td><td class="numeric"><b>'+money(r[3]-r[4])+'</b></td><td>'+r[5]+'</td><td><button class="po-link" data-debtor="'+r[1]+'">View →</button></td></tr>').join('')||empty(8),'Balances include Sales Invoices, customer credit notes, debit notes and receipts.')+'<p class="legend">Customer receivables remain separate from supplier payables. Recording a receipt does not change frozen Sales Invoice cost or GP.</p>';}
function bank(){const total=rows().filter(r=>!['PROBLEM','UNKNOWN'].includes(r.stage)).reduce((n,r)=>n+Math.max(0,r.request-r.paid),0);return title('Bank & Cash')+'<div class="money-cards">'+[[company==='NCT'?'MYR 82,450.00':'—','Recorded balance','Demo · 17 Oct 2026 09:00'],['MYR '+money(total),'Outstanding requests','Total outstanding demo requests; this is not an approved payment amount.'],[company==='NCT'?'MYR 16,000.00':'—','Expected collections','Demo forecast; excluded from recorded bank balances.']].map(([a,b,c])=>'<section class="money-card"><span>'+b+'</span><b>'+a+'</b><small>'+c+'</small></section>').join('')+'</div>'+toolbar('Bank · Reference · P.O.')+table([['Recorded At'],['Bank Account'],['Direction'],['Reference'],['P.O. No.'],['Currency'],['Amount','numeric'],['Recorded By'],['Proof']],[13,15,9,15,13,7,12,10,6],company==='NCT'?'<tr><td>17 Oct 2026 09:00</td><td>Maybank · ••••1208</td><td>Opening</td><td>BALANCE-DEMO</td><td>—</td><td>MYR</td><td class="numeric">82,450.00</td><td>ACCOUNT DEMO</td><td><button data-bank>View</button></td></tr><tr><td>16 Oct 2026 14:30</td><td>Maybank · ••••1208</td><td>Payment</td><td>PAY-DEMO-127</td><td>NCT-PO-00127</td><td>MYR</td><td class="numeric">−800.00</td><td>ACCOUNT DEMO</td><td><button class="slip" data-proof="00127">↓</button></td></tr>':empty(9),'Balances retain their source, recorder and timestamp. Forecasts and recorded transactions remain separate.')+'<div class="callout warning">Balance sources, bank accounts and entry permissions are pending agreement. This draft has no bank connection. Processing does not mean payment completed.</div>';}
function history(){return title('Transaction History')+toolbar('P.O. · Supplier · INV','<select aria-label="History year"><option>2026</option></select><select aria-label="History month"><option>October</option><option>All months</option></select>')+table([['Completed'],['P.O. No.'],['Supplier'],['Purchase For'],['Net MYR','numeric'],['Settlement'],['Pay Slip','center'],['Files'],['History']],[12,14,18,12,11,12,6,8,7],company==='NCT'?'<tr><td><b>15 Oct 2026</b><small>by ACCOUNT DEMO</small></td><td><button class="po-link" data-closed>NCT-PO-00110</button></td><td>HONG LEA</td><td>SCOMM</td><td class="numeric"><b>1,520.00</b></td><td><span class="pill green">Checked</span></td><td class="center"><button class="slip" data-closed>↓</button></td><td><button data-closed>PO · INV · DO · CN</button></td><td><button data-closed>History</button></td></tr>':empty(9),'Keep the complete transaction, payment proofs and Account action history.')+'<div class="callout">Closure requires settled payment, complete required documents and CN treatment, resolved receiving issues, a valid Finance Checked and the customer Sales Invoice. Fully Paid alone does not close the transaction.</div>';}
const baseEvents=()=>company==='NCT'?[{po:'NCT-PO-00128',supplier:'KOH SOON HUAT',at:'16 Oct 2026 14:35',by:'ACCOUNT DEMO',action:'Payment recorded',note:'MYR 650.00 · PAY-DEMO-128'},{po:'NCT-PO-00125',supplier:'HONG LEA',at:'16 Oct 2026 10:15',by:'ACCOUNT DEMO',action:'Reviewing',note:'Purchase request received for review'},{po:'NCT-PO-00126',supplier:'KOH SOON HUAT',at:'15 Oct 2026 16:40',by:'ACCOUNT DEMO',action:'Returned',note:'Unclear invoice; replacement requested'}]:[];
const activityPreview=()=>[...events,...baseEvents()].slice(0,3).map(e=>'<p><b>'+e.action+'</b><br><small>'+e.po+' · '+e.at+'</small></p>').join('')||'<p>No activity</p>';
function activity(){const list=[...events,...baseEvents()];return title('Activity History')+toolbar('P.O. · Staff · Action','<select id="activityAction" aria-label="Action filter"><option>All Actions</option><option>Reviewing</option><option>Payment</option><option>Returned</option></select>')+table([['Date & Time'],['Staff'],['Action'],['Reference'],['Details']],[16,14,24,20,26],list.map(e=>'<tr><td>'+e.at+'</td><td>'+e.by+'</td><td><b>'+e.action+'</b></td><td>'+e.po+'<small>'+e.supplier+'</small></td><td>'+esc(e.note)+'</td></tr>').join('')||empty(5),'Review, ownership, returns, amount and CN decisions, proofs, payment results and closure retain the time, staff member and reason.');}
function render(){if($('#detail').open)$('#detail').close();$('#nav').innerHTML=pages.map(([key,en])=>'<button data-page="'+key+'" class="'+(view===key?'active':'')+'" '+(view===key?'aria-current="page"':'')+'>'+en+'</button>').join('');$('#draftApp').innerHTML=({dashboard,payments,requests:payments,creditor,debtor,bank,history,activity}[view]||dashboard)();applySearch();}
function applySearch(){const tr=[...document.querySelectorAll('#draftApp tbody tr')].filter(r=>!r.querySelector('.empty'));let n=0;for(const row of tr){row.hidden=!row.textContent.toLowerCase().includes(query.trim().toLowerCase())||(view==='activity'&&actionFilter&&!row.textContent.toLowerCase().includes(actionFilter));if(!row.hidden)n++;}const count=$('#count');if(count)count.textContent=n+' record'+(n===1?'':'s');let no=$('#noSearch');if(no)no.remove();if(!n&&tr.length){const body=$('#draftApp tbody');if(body)body.insertAdjacentHTML('beforeend','<tr id="noSearch"><td colspan="'+$('#draftApp thead tr').children.length+'" class="empty">No matching records</td></tr>');}}
function modal(r,heading,body,actions=''){const closed=!r;$('#detailTitle').innerHTML='<h2>'+esc(r?r.supplier:'Account')+'</h2><p>'+heading+'</p><small>'+esc(r?company+' · '+po(r):'Discussion draft')+'</small>';$('#detailBody').innerHTML=body;$('#detailActions').innerHTML='<button data-dismiss>Close</button>'+actions;$('#detail').showModal();}
function detail(r){const remaining=Math.max(0,r.request-r.paid),locked=r.stage!=='NEW';modal(r,'Payment Request','<div class="facts">'+[['Requested',r.request],['Paid',r.paid],['Remaining',remaining],['CN',r.cn]].map(([label,n])=>'<div><small>'+label+' MYR</small><b>'+money(n)+'</b></div>').join('')+'</div><p>'+pill(r)+' <span style="margin-left:10px">'+(locked?'🔒 Purchase editing is locked until Account returns the request.':'Purchase can edit until Account takes ownership.')+'</span></p><div class="fields"><div><small>Requested</small><p>'+r.at+' · '+r.by+'</p></div><div><small>Purchase For</small><p>'+r.customer+' · ETA '+r.eta+'</p></div><div><small>Purpose</small><p>'+r.purpose+'</p></div><div><small>Term</small><p>'+r.term+' · '+r.due+'</p></div></div>'+(r.note?'<div class="request-note"><b>Note from Purchase</b><p>'+esc(r.note)+'</p></div>':'')+'<h3 class="section-heading">Supporting Documents</h3><table><thead><tr><th>Document</th><th class="numeric">Amount MYR</th><th>Check</th></tr></thead><tbody><tr><td>Our PO · '+po(r)+'</td><td class="numeric">Reference</td><td><button data-demo-doc>View</button></td></tr><tr><td>'+r.basis+' · '+r.basis+'-'+r.id+'</td><td class="numeric">'+money(r.invoice)+'</td><td><button data-demo-doc>View</button></td></tr>'+(r.cn?'<tr><td>CN · CN-'+r.id+'</td><td class="numeric">−'+money(r.cn)+'</td><td>Deduct</td></tr>':'')+'</tbody></table><h3 class="section-heading">Note from Account</h3><p>'+esc(r.accNote||'No note yet')+'</p><h3 class="section-heading">History</h3><div class="timeline"><p>Request submitted<small>'+r.at+' · '+r.by+'</small></p>'+events.filter(e=>e.po===po(r)).map(e=>'<p>'+e.action+'<small>'+e.at+' · '+e.by+'</small>'+esc(e.note)+'</p>').join('')+'</div>',r.stage==='NEW'?'<button class="btn-primary" data-take="'+r.id+'">Reviewing</button>':r.stage==='UNKNOWN'?'<button class="btn-action problem" data-resolve="'+r.id+'">Resolve bank result</button>':r.stage==='PAID'?'<button data-reconcile="'+r.id+'">Review closeout</button>':r.stage==='PROBLEM'?'<button data-problem>Awaiting Purchase</button>':r.stage==='PROCESSING'?'<button class="btn-primary" data-record-open="'+r.id+'">Record Bank Result</button>':'<button data-return="'+r.id+'">Return to Purchase</button><button class="btn-primary" '+(r.reviewed?'data-start-payment':'data-review')+'="'+r.id+'">'+(r.reviewed?'Mark Processing':'Review Payment')+'</button>');}
function review(r){modal(r,'Review Payment','<div class="callout">Check the request version, supporting documents and CN treatment. Review completion does not record a payment.</div><div class="checklist"><label><input type="checkbox" class="review-check"> Supplier and bank details are correct</label><label><input type="checkbox" class="review-check"> '+r.basis+' amount and current version checked</label><label><input type="checkbox" class="review-check"> CN treatment and prior payments checked</label></div><h3 class="section-heading">Note from Account</h3><textarea id="reviewNote" rows="2" placeholder="Reconciliation note"></textarea>','<button class="btn-primary" data-ready="'+r.id+'">Confirm review</button>');}
function record(r){proofSelected=false;modal(r,'Record Payment','<div class="callout warning">Record an existing bank result and its proof. This does not execute a transfer. The draft simulates the record only.</div><div class="fields"><label>Paid Amount MYR<input id="paidAmount" type="number" step="0.01" min="0.01" value="'+((r.request-r.paid)/100).toFixed(2)+'"></label><label>Bank Reference<input id="paidReference" value="PAY-DEMO-'+r.id+'"></label></div><p><button id="demoProof">Use demo pay slip</button><span id="proofState" style="margin-left:10px">No proof</span></p><textarea id="paidNote" rows="2" placeholder="Note from Account"></textarea>','<button class="btn-green" data-record="'+r.id+'">Record demo payment</button>');}
function gates(r){modal(r,'Transaction Closeout','<div class="gate"><span class="done">✓</span> Supplier payment settled</div>'+[['Final Invoice and DO',true],['CN handled or marked not applicable',true],['Warehouse and shortage resolved',false],['Current Finance Checked',false],['Customer Sales Invoice',false]].map(([label,done])=>'<div class="gate"><span class="'+(done?'done':'pending')+'">'+(done?'✓':'○')+'</span>'+label+'</div>').join('')+'<div class="callout">Fully Paid applies to this request. The transaction remains open until all closure requirements are met.</div>');}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;applySearch();}});
document.addEventListener('change',e=>{if(e.target.id==='company'){company=e.target.value;query='';events=[];render();}if(e.target.id==='requestFilter'){filter=e.target.value;query='';render();}if(e.target.id==='activityAction'){actionFilter=e.target.selectedIndex?e.target.value.toLowerCase():'';applySearch();}});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset,id=d.open||d.take||d.review||d.ready||d.return||d.record||d.proof||d.reconcile||d.resolve,r=rows().find(r=>r.id===id);
 if(d.page){view=d.page;query='';filter='ALL';actionFilter='';render();return;}if(d.queue){view='requests';query='';filter=d.queue;render();return;}if(b.id==='reset'){requests=structuredClone(seed);events=[];query='';filter='ALL';render();showNotice('Demo reset');return;}if(b.id==='close'||'dismiss'in d){$('#detail').close();return;}if('refresh'in d){showNotice('Demo data refreshed');return;}
 if(d.open&&r){detail(r);return;}if(d.take&&r){r.stage='REVIEW';audit(r,'Reviewing','Purchase editing is locked until Account confirms a return.');render();detail(r);return;}if(d.review&&r){review(r);return;}
 if(d.ready&&r){if([...document.querySelectorAll('.review-check')].some(c=>!c.checked)){showNotice('Complete all checks');return;}r.accNote=$('#reviewNote').value||'Payment request verified';r.reviewed=true;audit(r,'Payment reviewed',r.accNote);render();detail(r);return;}
 if(d.startPayment){const row=rows().find(r=>r.id===d.startPayment);modal(row,'Payment Processing','<div class="callout warning">Mark Processing only after a bank payment has started. It does not mean Paid. Block another payment attempt or return while processing.</div><label><input id="bankClear" type="checkbox"> No unresolved previous payment</label>','<button class="btn-action" data-processing-confirm="'+row.id+'">Confirm demo processing</button>');return;}
 if(d.processingConfirm){const row=rows().find(r=>r.id===d.processingConfirm);if(!$('#bankClear').checked){showNotice('Confirm bank status');return;}row.stage='PROCESSING';audit(row,'Payment processing','Demo processing started; payment is not yet confirmed.');render();detail(row);return;}
 if(d.recordOpen){record(rows().find(r=>r.id===d.recordOpen));return;}
 if(b.id==='demoProof'){proofSelected=true;$('#proofState').textContent='✓ Demo PDF ready';return;}
 if(d.record&&r){const cents=Math.round(Number($('#paidAmount').value)*100);if(!r.reviewed||!proofSelected||!(cents>0)||cents>r.request-r.paid||!$('#paidReference').value.trim()){showNotice('Check amount, reference and proof');return;}r.paid+=cents;r.proof=true;r.stage=r.paid>=r.request?'PAID':'PARTIAL';r.accNote=$('#paidNote').value||'Payment proof recorded';audit(r,'Payment recorded','MYR '+money(cents)+' · '+$('#paidReference').value);render();detail(r);return;}
 if(d.return&&r){modal(r,'Return to Purchase','<div class="callout warning">Return is allowed only when no bank payment is processing or unknown. A reason is required. Keep the original request and Account history.</div><label>Reason<textarea id="returnNote" rows="3" placeholder="Please explain"></textarea></label>','<button class="btn-action problem" data-return-confirm="'+r.id+'">Confirm demo return</button>');return;}
 if(d.returnConfirm){const row=rows().find(r=>r.id===d.returnConfirm),note=$('#returnNote').value.trim();if(!note){showNotice('Reason required');return;}row.stage='PROBLEM';row.accNote=note;audit(row,'Returned',note);render();detail(row);return;}
 if(d.resolve&&r){modal(r,'Resolve Bank Result','<div class="callout problem">An unknown bank result blocks another payment attempt and return to Purchase.</div><p>Demo: confirm with the bank that no payment occurred, then resume review. An actual payment must be linked to its proof.</p>','<button class="btn-primary" data-not-paid="'+r.id+'">Demo: confirmed unpaid</button>');return;}
 if(d.notPaid){const row=rows().find(r=>r.id===d.notPaid);row.stage='REVIEW';audit(row,'Bank result resolved','Demo: confirmed unpaid; review may resume.');render();detail(row);return;}
 if(d.reconcile&&r){gates(r);return;}if(d.proof){modal(r,'Pay Slip','<div class="callout">Demo payment proof. The production View action will open the corresponding Google Drive file through the existing mechanism.</div><p><b>PAY-DEMO-'+id+'</b></p><p>PDF · Uploaded by ACCOUNT DEMO</p>');return;}
 if('demoDoc'in d){showNotice('Demo document only');return;}
 if('closed'in d){modal(null,'Completed Transaction','<p><b>NCT-PO-00110 · HONG LEA</b></p><div class="facts"><div><small>Net MYR</small><b>1,520.00</b></div><div><small>Paid MYR</small><b>1,520.00</b></div></div><p><span class="pill green">Checked</span></p><p>Our PO · INV · DO · CN · Pay Slip</p><div class="timeline"><p>Finance Checked<small>15 Oct 2026 16:20 · ACCOUNT DEMO</small></p><p>Payment recorded<small>15 Oct 2026 15:45 · ACCOUNT DEMO</small></p></div>');return;}
 if(d.debtor){modal(null,'Customer Ledger','<p><b>'+esc(d.debtor)+'</b></p><p>Sales Invoice → Receipts → CN or Debit Note adjustments → Outstanding balance</p><div class="callout">Show the original invoice, each receipt proof and balance changes. This is a draft. Customer receipts remain separate from supplier payments.</div>');return;}
 if('credit'in d){modal(null,'Supplier Credit','<p>HONG LEA · CN-DEMO-09 · MYR 50.00</p><div class="callout">Apply credit only to eligible POs for the same company and supplier. Record the amount, target PO, staff member and time. Do not deduct the same credit twice.</div>');return;}
 if('legacy'in d){modal(null,'Legacy Reconciliation','<p>Retain legacy POs and existing payment records.</p><div class="callout warning">Reconcile the actual bank result, existing proofs and supplier balance before taking ownership through the existing flow. Do not automatically treat legacy POs as new unpaid requests.</div>');return;}
 if('bank'in d){showNotice('Recorded balance source and entry process pending agreement');return;}if('problem'in d)showNotice('Waiting for corrected documents');
});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();});render();
})();
